// date's members: one function per member, each declared by the //kavun:member directive in its doc comment. The table,
// dateMethods, and the member entries of docs/reference/types/date.md (alphabetical, so the order here is free) are
// generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// The default render and `#date`/`#iso` are `YYYY-MM-DD`; a `%`-template takes the date directives
// (`%Y %y %C %m %d %e %j %B %b %A %a %u %w %V %G %n %t %%`). Clock and zone directives, and the clock-bearing
// aliases (`#datetime`, `#time`, `#unix`, …), raise:
//
// ```go
// d := d"2026-01-31"
// f"{d}"                      // => "2026-01-31"
// f"{d:#%d/%m/%Y}"            // => "31/01/2026"
// f"{d:#%A %e %B %Y}"         // => "Saturday 31 January 2026"
// f"{d:v}"                    // `date("2026-01-31")` — the source form
// d.format("#%H")             // Error: formatting: directive %H is not available on a date
// ```
//
//kavun:member format pure ([spec]) -> string
func dateFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Report truthiness: `date()`, `1970-01-01`, is falsy (`!!x` ⟺ `x != date()`).
//
// Derived like every type's: `date()` (`1970-01-01`) is falsy, every other day is truthy — including `0001-01-01`
// and `9999-12-31`, the sentinels other systems use for "unset" and "no end". A host that means "missing" by one
// should map it to `undefined`.
//
//kavun:member is_true pure () -> bool
func dateIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Answer the receiver — a `date` is always immutable.
//
// Identity no-ops on an immutable scalar, kept so generic code never type-errors.
//
//kavun:member copy pure () -> date
func dateCopy(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver — a `date` is always immutable; see [`copy`](#copy).
//
//kavun:member freeze pure () -> date
func dateFreeze(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver, the identity conversion.
//
//kavun:member date pure ([default]) -> date
func dateDate(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), dateTypeName, args, true, v)
}

// Answer the epoch days, the count since `1970-01-01`.
//
// ```go
// d := d"2026-01-31"
// d.int()                     // => 20484 — epoch days; (20484).date() is the way back
// ```
//
//kavun:member int pure ([default]) -> int
func dateInt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d := DateOf(v)
	return ConvMember(id.String(), dateTypeName, args, true, IntValue(int64(d.Days())))
}

// Answer the canonical text, `YYYY-MM-DD`.
//
// ```go
// d := d"2026-01-31"
// d.string()                  // => "2026-01-31"
// ```
//
//kavun:member string pure ([default]) -> string
func dateString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d := DateOf(v)
	return ConvMember(id.String(), dateTypeName, args, true, NewStringValue(d.String()))
}

// Answer the canonical text as `runes`; see [`string`](#string).
//
// ```go
// d := d"2026-01-31"
// d.runes()                   // => u"2026-01-31"
// ```
//
//kavun:member runes pure ([default]) -> runes
func dateRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d := DateOf(v)
	return ConvMember(id.String(), dateTypeName, args, true, NewRunesValue(text.DecodeText(d.String()), false))
}

// Answer midnight UTC of the day; see [the time bridge](#the-time-bridge).
//
// ```go
// d := d"2026-01-31"
// d.time()                    // midnight UTC
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member time pure ([default]) -> time
func dateTime(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d := DateOf(v)
	// midnight UTC — the date's own reading; time_in(zone) is the start of the day elsewhere
	return ConvMember(id.String(), dateTypeName, args, true, NewTimeValue(dateMidnightUTC(d)))
}

// Answer the record `{year, month, day}`, the way back through `date(rec)`.
//
// ```go
// d := d"2026-01-31"
// d.components()              // => {"day": 31, "month": 1, "year": 2026}
// date(d.components()) == d   // => true
// ```
//
//kavun:member components pure () -> record
func dateComponents(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	d := DateOf(v)
	y, m, dd := d.YMD()
	return NewRecordValue(map[string]Value{
		"year":  IntValue(int64(y)),
		"month": IntValue(int64(m)),
		"day":   IntValue(int64(dd)),
	}, false), nil
}

