// Move by `n` days, exactly `d + n`; see [`add_months`](#add_months).
//
//kavun:member add_days pure (n) -> date
func dateAddDays(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	d := DateOf(v)
	n, err := parseIntArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	return dateShiftDays(d, n)
}

// Move by `n` calendar months with the end-of-month `rule`.
//
// `add_days(n)` is `d + n`. Month and year steps take a **required** end-of-month rule, which only matters when
// the start is a month end:
//
// | rule | meaning |
// | --- | --- |
// | `"clamp"` | keep the day of the month, clamped to the target month's length |
// | `"last_day"` | a month-end start stays a month end |
//
// ```go
// d"2026-01-31".add_months(1, "clamp")      // => date("2026-02-28")
// d"2026-04-30".add_months(1, "clamp")      // => date("2026-05-30")
// d"2026-04-30".add_months(1, "last_day")   // => date("2026-05-31")
// d"2024-02-29".add_years(1, "clamp")       // => date("2025-02-28")
// d"2023-02-28".add_years(1, "last_day")    // => date("2024-02-29")
// d"2026-01-31".add_months(1)               // Error: wrong_num_arguments — state the rule
// ```
//
//kavun:member add_months pure (n, rule) -> date
func dateAddMonths(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	d := DateOf(v)
	n, err := parseIntArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	rule, err := EOMRuleArg(name, "second", args[1])
	if err != nil {
		return Undefined, err
	}
	if n < -1<<31 || n > 1<<31-1 {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) result out of range", name))
	}
	r, ok := d.AddMonths(int32(n), rule)
	if !ok {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) result out of range", name))
	}
	return DateValue(r), nil
}

// Move by `n` calendar years with the end-of-month `rule`; see [`add_months`](#add_months).
