// Answer the whole months and the leftover days from `other` to the receiver, the inverse of `add_months`.
//
// `months_since(other, rule)` is their inverse: `[months, days]` — the whole months from `other` to the receiver
// and the days left over, so that `other.add_months(months, rule) + days` is the receiver. Both are negative when
// the receiver is earlier:
//
// ```go
// d"2026-05-31".months_since(d"2026-01-31", "clamp")     // => [4, 0]
// d"2026-05-30".months_since(d"2026-04-30", "last_day")  // => [0, 30] — the month step would land on 31 May
// d"2026-01-01".months_since(d"2026-03-15", "clamp")     // => [-2, -14]
// m, days := d"2026-07-20".months_since(d"2026-01-31", "clamp")   // destructures positionally
// ```
//
//kavun:member months_since pure (other, rule) -> [months, days]
func dateMonthsSince(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	d := DateOf(v)
	// [months, days]: whole months from other to d, and the days left over, so that
	// other.add_months(months, rule) + days == d
	if args[0].Type != value.Date {
		return Undefined, errs.NewInvalidArgumentTypeError(name, "first", "date", args[0].TypeName())
	}
	rule, err := EOMRuleArg(name, "second", args[1])
	if err != nil {
		return Undefined, err
	}
	months, days, ok := d.MonthsSince(DateOf(args[0]), rule)
	if !ok {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) result out of range", name))
	}
	return NewArrayValue([]Value{IntValue(int64(months)), IntValue(int64(days))}, false), nil

	// bridge to time
}

// Answer the first instant of the day in the named zone; see [the time bridge](#the-time-bridge).
//
//kavun:member time_in pure (zone) -> time
func dateTimeIn(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	d := DateOf(v)
	loc, err := zoneArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	return NewTimeValue(dateStartIn(d, loc)), nil
}
